public class Main {
    static double combination(int n, int k) {
        int nf = 1, kf = 1, nkf = 1;
        for (int i = 2; i <= n; i++) nf *= i;
        for (int i = 2; i <= k; i++) kf *= i;
        for (int i = 2; i <= n - k; i++) nkf *= i;
        return nf / (double) (kf * nkf);
    }
    public static void main(String[] args) {
        System.out.println(combination(5, 2));
    }
}

