    static class Digit {
        private int num;
        Digit(int n) { num = n; }
        int digitMultiplication() {
            int n = num, ans = 1;
            while (n > 0) { ans *= n % 10; n /= 10; }
            return ans;
        }
        void output() {
            System.out.println("The digit multiplication of : " + num + " is " + digitMultiplication());
        }
    }
    public static void main(String[] args) {
        new Digit(4567).output();
    }
}

